ALTER TABLE public.schemes
  ADD COLUMN IF NOT EXISTS education_levels text[] NOT NULL DEFAULT '{}'::text[],
  ADD COLUMN IF NOT EXISTS caste_categories text[] NOT NULL DEFAULT '{}'::text[],
  ADD COLUMN IF NOT EXISTS area_type text NOT NULL DEFAULT 'any',
  ADD COLUMN IF NOT EXISTS department text,
  ADD COLUMN IF NOT EXISTS official_website text,
  ADD COLUMN IF NOT EXISTS last_updated timestamptz NOT NULL DEFAULT now();

UPDATE public.schemes SET official_website = apply_url WHERE official_website IS NULL;
UPDATE public.schemes SET department = ministry WHERE department IS NULL;

-- remove duplicates by name (keep oldest)
DELETE FROM public.schemes a USING public.schemes b
WHERE a.name = b.name AND coalesce(a.state,'') = coalesce(b.state,'') AND a.ctid > b.ctid;

ON CONFLICT (slug) DO NOTHING;